WHENEVER OSERROR EXIT FAILURE ROLLBACK
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
SET SERVEROUTPUT ON
DECLARE
  n NUMBER;
  default_text LONG;
BEGIN
  IF SYS_CONTEXT('USERENV','SESSION_USER') IN ('SYS','SYSTEM') OR
     SYS_CONTEXT('USERENV','CURRENT_SCHEMA') <> SYS_CONTEXT('USERENV','SESSION_USER') THEN
    RAISE_APPLICATION_ERROR(-20200, 'Connect as the installation user'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TABLES;
  IF n <> 10 THEN RAISE_APPLICATION_ERROR(-20201, 'Unexpected installation tables'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME IN ('T_CRM_CONTRACT','T_CRM_INVOICE_PROJ','T_CRM_INVOICE','T_CRM_PAY_PROJECT','T_CRM_PAYMENT','T_LIMS_CLEARANCEFORM','T_LIMS_FOLDERS','T_XFP_ORDER_TASK','T_XFP_PROJECT','T_XFP_REPORT');
  IF n <> 10 THEN RAISE_APPLICATION_ERROR(-20201, 'External table closure differs'); END IF;
  SELECT COUNT(*) INTO n FROM USER_OBJECTS WHERE OBJECT_TYPE NOT IN ('TABLE','INDEX','LOB');
  IF n <> 0 THEN RAISE_APPLICATION_ERROR(-20201, 'Unexpected installation objects'); END IF;
  SELECT COUNT(*) INTO n FROM USER_DB_LINKS;
  IF n <> 0 THEN RAISE_APPLICATION_ERROR(-20201, 'Database links are outside this package'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TRIGGERS WHERE TABLE_NAME IN ('T_CRM_CONTRACT','T_CRM_INVOICE_PROJ','T_CRM_INVOICE','T_CRM_PAY_PROJECT','T_CRM_PAYMENT','T_LIMS_CLEARANCEFORM','T_LIMS_FOLDERS','T_XFP_ORDER_TASK','T_XFP_PROJECT','T_XFP_REPORT');
  IF n <> 0 THEN RAISE_APPLICATION_ERROR(-20201, 'Unexpected external table trigger'); END IF;
END;
