DECLARE
  n NUMBER;
  default_text LONG;
  TYPE column_map IS TABLE OF VARCHAR2(2000) INDEX BY VARCHAR2(128);
  actual column_map;
BEGIN
  SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='T_CRM_INVOICE_PROJ' AND TEMPORARY='N' AND NESTED='NO' AND SECONDARY='N' AND PARTITIONED='NO';
  IF n <> 1 THEN RAISE_APPLICATION_ERROR(-20201, 'Table differs: T_CRM_INVOICE_PROJ'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TAB_COLS WHERE TABLE_NAME='T_CRM_INVOICE_PROJ';
  IF n <> 33 THEN RAISE_APPLICATION_ERROR(-20201, 'Column closure differs: T_CRM_INVOICE_PROJ'); END IF;
  FOR c IN (SELECT COLUMN_NAME,COLUMN_ID,DATA_TYPE,DATA_LENGTH,DATA_PRECISION,DATA_SCALE,
                   NULLABLE,CHAR_USED,CHAR_LENGTH,HIDDEN_COLUMN,VIRTUAL_COLUMN,DEFAULT_LENGTH
            FROM USER_TAB_COLS WHERE TABLE_NAME='T_CRM_INVOICE_PROJ') LOOP
    actual(c.COLUMN_NAME) := c.COLUMN_ID || '|' || c.DATA_TYPE || '|' ||
      NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') || '|' ||
      c.NULLABLE || '|' || c.HIDDEN_COLUMN || '|' || c.VIRTUAL_COLUMN || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DEFAULT_LENGTH IS NULL THEN 'none' ELSE 'present' END;
  END LOOP;
  IF NOT actual.EXISTS('ID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_CRM_INVOICE_PROJ.ID'); END IF;
  IF actual('ID') <> '1|NUMBER|-|-|N|NO|NO|-|-|-|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_CRM_INVOICE_PROJ.ID'); END IF;
  IF NOT actual.EXISTS('SOURCETYPE') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_CRM_INVOICE_PROJ.SOURCETYPE'); END IF;
  IF actual('SOURCETYPE') <> '2|VARCHAR2|-|-|Y|NO|NO|120|B|120|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_CRM_INVOICE_PROJ.SOURCETYPE'); END IF;
