DECLARE
  n NUMBER;
  default_text LONG;
  TYPE column_map IS TABLE OF VARCHAR2(2000) INDEX BY VARCHAR2(128);
  actual column_map;
BEGIN
  SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='T_CRM_PAY_PROJECT' AND TEMPORARY='N' AND NESTED='NO' AND SECONDARY='N' AND PARTITIONED='NO';
  IF n <> 1 THEN RAISE_APPLICATION_ERROR(-20201, 'Table differs: T_CRM_PAY_PROJECT'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TAB_COLS WHERE TABLE_NAME='T_CRM_PAY_PROJECT';
  IF n <> 15 THEN RAISE_APPLICATION_ERROR(-20201, 'Column closure differs: T_CRM_PAY_PROJECT'); END IF;
  FOR c IN (SELECT COLUMN_NAME,COLUMN_ID,DATA_TYPE,DATA_LENGTH,DATA_PRECISION,DATA_SCALE,
                   NULLABLE,CHAR_USED,CHAR_LENGTH,HIDDEN_COLUMN,VIRTUAL_COLUMN,DEFAULT_LENGTH
            FROM USER_TAB_COLS WHERE TABLE_NAME='T_CRM_PAY_PROJECT') LOOP
    actual(c.COLUMN_NAME) := c.COLUMN_ID || '|' || c.DATA_TYPE || '|' ||
      NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') || '|' ||
      c.NULLABLE || '|' || c.HIDDEN_COLUMN || '|' || c.VIRTUAL_COLUMN || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DEFAULT_LENGTH IS NULL THEN 'none' ELSE 'present' END;
