DECLARE
  n NUMBER;
  default_text LONG;
  TYPE column_map IS TABLE OF VARCHAR2(2000) INDEX BY VARCHAR2(128);
  actual column_map;
BEGIN
  SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='T_XFP_ORDER_TASK' AND TEMPORARY='N' AND NESTED='NO' AND SECONDARY='N' AND PARTITIONED='NO';
  IF n <> 1 THEN RAISE_APPLICATION_ERROR(-20201, 'Table differs: T_XFP_ORDER_TASK'); END IF;
  SELECT COUNT(*) INTO n FROM USER_TAB_COLS WHERE TABLE_NAME='T_XFP_ORDER_TASK';
  IF n <> 39 THEN RAISE_APPLICATION_ERROR(-20201, 'Column closure differs: T_XFP_ORDER_TASK'); END IF;
  FOR c IN (SELECT COLUMN_NAME,COLUMN_ID,DATA_TYPE,DATA_LENGTH,DATA_PRECISION,DATA_SCALE,
                   NULLABLE,CHAR_USED,CHAR_LENGTH,HIDDEN_COLUMN,VIRTUAL_COLUMN,DEFAULT_LENGTH
            FROM USER_TAB_COLS WHERE TABLE_NAME='T_XFP_ORDER_TASK') LOOP
    actual(c.COLUMN_NAME) := c.COLUMN_ID || '|' || c.DATA_TYPE || '|' ||
      NVL(TO_CHAR(c.DATA_PRECISION),'-') || '|' || NVL(TO_CHAR(c.DATA_SCALE),'-') || '|' ||
      c.NULLABLE || '|' || c.HIDDEN_COLUMN || '|' || c.VIRTUAL_COLUMN || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR','RAW') THEN TO_CHAR(c.DATA_LENGTH) ELSE '-' END || '|' ||
      CASE WHEN c.DATA_TYPE IN ('VARCHAR2','CHAR','NVARCHAR2','NCHAR') THEN c.CHAR_USED || '|' || TO_CHAR(c.CHAR_LENGTH) ELSE '-|-' END || '|' ||
      CASE WHEN c.DEFAULT_LENGTH IS NULL THEN 'none' ELSE 'present' END;
  END LOOP;
  IF NOT actual.EXISTS('ID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_XFP_ORDER_TASK.ID'); END IF;
  IF actual('ID') <> '1|NUMBER|19|0|N|NO|NO|-|-|-|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_XFP_ORDER_TASK.ID'); END IF;
  IF NOT actual.EXISTS('PROJID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_XFP_ORDER_TASK.PROJID'); END IF;
  IF actual('PROJID') <> '2|NUMBER|19|0|Y|NO|NO|-|-|-|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_XFP_ORDER_TASK.PROJID'); END IF;
  IF NOT actual.EXISTS('ORDERID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_XFP_ORDER_TASK.ORDERID'); END IF;
  IF actual('ORDERID') <> '3|NUMBER|19|0|Y|NO|NO|-|-|-|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_XFP_ORDER_TASK.ORDERID'); END IF;
  IF NOT actual.EXISTS('TASKID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_XFP_ORDER_TASK.TASKID'); END IF;
  IF actual('TASKID') <> '4|NUMBER|19|0|Y|NO|NO|-|-|-|none' THEN RAISE_APPLICATION_ERROR(-20201, 'Column differs: T_XFP_ORDER_TASK.TASKID'); END IF;
  IF NOT actual.EXISTS('CREATEDBYID') THEN RAISE_APPLICATION_ERROR(-20201, 'Column missing: T_XFP_ORDER_TASK.CREATEDBYID'); END IF;
